sited.script:

    // 核心的「內容列表」解析函式
    function list_parse(url, jsontext) {
        try {
            const response = JSON.parse(jsontext);
            if (!response || !response.data || !Array.isArray(response.data.items)) {
                return JSON.stringify([]);
            }
            const list = response.data.items.map(item => ({
                logo: item.thumbnail.replace(/^http:/, 'https:'),
                name: gbk2big5.traditionalized(item.title),
                // API 回傳的 URL 可能是 http，手動換成 https 增加安全性
                url: item.url.replace(/^http:/, 'https:')
            }));
            return JSON.stringify(list);
        } catch (error) {
            return JSON.stringify([]);
        }
    }

    // 解析文章詳情頁 (Book)，僅作導航用途
    function book_parse(url, html) {
        const $ = cheerio.load(html);
        const name = $('meta[property="og:title"]').attr('content') || $('title').text();
        const logo = $('meta[property="og:image"]').attr('content');
        const sections = [{
            name: "閱讀全文",
            url: url.replace(/^http:/, 'https:')
        }];
        const book = {
            name: gbk2big5.traditionalized(name),
            logo: logo,
            intro: gbk2big5.traditionalized("點擊下方 '閱讀全文' 開始閱讀"),
            sections: sections
        };
        return JSON.stringify(book);
    }

// ⭐【核心修正 V11 - 解決圖文順序與圖片缺失問題 (基於字串解析)】
function section_parse(url, html) {
    const $ = cheerio.load(html);
    const data = [];

    const articleContent = $('article#article-detail-content');

    if (articleContent.length === 0) {
        return JSON.stringify({type:"article", data: data});
    }

    // 遍歷文章內容的所有直接子元素 (<p>, <center>, <div>, etc.)
    articleContent.children().each(function() {
        const element = $(this);
        const elementHtml = element.html() || ''; 

        // ----------------------------------------------------
        // 1. 處理嵌入元素 (div.twitter-tweet) - 避免複雜解析
        // ----------------------------------------------------
        if (element.is('div')) {
             const elementClass = element.attr('class') || '';
             if (elementClass.includes('twitter-tweet')) {
                const $$$$ = cheerio.load(elementHtml);
                const iframe = $$$$('iframe');
                if (iframe.length > 0) {
                    data.push({ t: "text", d: gbk2big5.traditionalized("[外部內容: 嵌入式內容]") });
                    return; 
                }
             }
        }

        // ----------------------------------------------------
        // 2. 處理圖文混合元素 (P, Hx, BLOCKQUOTE 等)
        // ----------------------------------------------------
        if (element.is('p') || element.is('h1, h2, h3, h4, h5, h6') || element.is('li') || element.is('blockquote') || element.is('center')) {
            if (!elementHtml) return;

            // 使用正則表達式將圖片標籤從內容中分離出來，同時保留順序
            // 匹配圖片標籤或任意非圖片/非標籤文本 (包括 <br>)
            const regex = /<img[^>]*src="([^"]+)"[^>]*>|([\s\S]*?(?=<img|$))/gi;
            let match;
            let lastIndex = 0;

            // 確保元素本身是 <center> 時，也能被正確解析，先移除頂層 <center>
            let cleanHtml = elementHtml.replace(/^<center>|<\/center>$/gi, ''); 

            while ((match = regex.exec(cleanHtml)) !== null) {
                // 處理匹配到的文本部分 (match[2])
                let textChunk = match[2];
                if (textChunk && textChunk.trim().length > 0) {

                    // ------------------ 文本處理邏輯 ------------------
                    let rawHtml = textChunk;

                    // 1. 臨時標記 <strong> 內部的內容 (保留粗體資訊)
                    rawHtml = rawHtml.replace(/<strong[^>]*>([\s\S]*?)<\/strong>/gi, '@@BOLD@@$1@@/BOLD@@');

                    // 2. 移除 a/span/font 標籤，保留內容 (移除樣式和連結標籤)
                    rawHtml = rawHtml.replace(/<span[^>]*>([\s\S]*?)<\/span>/gi, '$1'); 
                    rawHtml = rawHtml.replace(/<a[^>]*>([\s\S]*?)<\/a>/gi, '$1'); 
                    rawHtml = rawHtml.replace(/<font[^>]*>([\s\S]*?)<\/font>/gi, '$1'); 

                    // 3. 移除所有其他不必要的 HTML 標籤
                    let text = rawHtml.replace(/<(?!\/?br\s*\/?)[^>]+>/gi, '');

                    // 4. 將 <br> 替換為換行並清理
                    text = text.replace(/<br\s*\/?>/gi, '\n').trim();
                    text = text.replace(/(\n[ \t]*){2,}/g, '\n\n');
                    text = text.replace(/^[ \t]+/gm, ''); 

                    if (text) {
                        const lines = text.split('\n');

                        lines.forEach(line => {
                            line = line.trim();
                            if (line) {
                                const parts = line.split(/(@@BOLD@@.*?@@\/BOLD@@)/g).filter(p => p.trim() !== '');

                                parts.forEach(part => {
                                    let partIsBold = part.startsWith('@@BOLD@@');
                                    let partText = part.replace(/@@BOLD@@|@@\/BOLD@@/g, '').trim(); 

                                    if (partText) {
                                        // V9 解碼技巧
                                        let decodedText = cheerio.load('<div>' + partText + '</div>')('div').text();

                                        data.push({ t: "text", d: gbk2big5.traditionalized(decodedText), b: partIsBold ? 1 : undefined });
                                    }
                                });
                            }
                        });
                    }
                }

                // 處理匹配到的圖片部分 (match[1] 是 src 屬性)
                let src = match[1];
                if (src) {
                    // ------------------ 圖片處理邏輯 ------------------
                    if (src.startsWith('//')) {
                        src = 'https:' + src;
                    }
                    src = src.replace(/^http:/, 'https:');

                    if (!src.includes('default_thumbnail.png')) {
                        data.push({ t: "image", d: src });
                    }
                }

                lastIndex = regex.lastIndex;
            }
        }
        // ------------------------------------
        // 3. 處理 <center> 標籤內部的裸圖片 (如果它不是 p 或 div)
        // 由於我們在 2 中已經包含了 element.is('center') 的處理，這部分應被 2 處理。
        // ------------------------------------
    });

    return JSON.stringify({type:"article", data: data});
}
